[tool.uv.workspace]
members = ["livekit-plugins/*", "livekit-agents", "examples/avatar", "examples/drive_thru", "examples/expressive_agent", "examples/frontdesk", "examples/healthcare", "examples/homepage", "examples/hotel_receptionist", "examples/inference", "examples/survey", "examples/voice_agents"]
exclude = [
    "livekit-plugins/community",
    "livekit-plugins/livekit-blockguard",
    "livekit-plugins/livekit-durable",
]

[dependency-groups]
dev = [
    "python-dotenv>=1.0.1",
    "mypy",
    "scikit-learn",
    "pytest>=9.0.3,<9.1",
    "ruff",
    "pytest-asyncio>=0.25.3",
    "pytest-asyncio-concurrent==0.5.2",
    "jiwer>=3.1.0",
    "scipy>=1.13.1",
    "tiktoken>=0.9.0",
    "pytest-xdist>=3.8.0",
    "playwright>=1.58.0",
]
docs = ["pdoc3", "setuptools", "beautifulsoup4", "markdownify"]
typing = [
    # .pyi stubs, never used at runtime
    "pandas-stubs>=3.0.3.260530",
    "scipy-stubs>=1.17.1.5",
    "types-aiofiles>=25.1.0.20260518",
    "types-cffi>=2.0.0.20260518",
    "types-defusedxml>=0.7.0.20260504",
    "types-grpcio>=1.0.0.20260607",
    "types-grpcio-status>=1.0.0.20260408",
    "types-gunicorn>=26.0.0.20260518",
    "types-openpyxl>=3.1.5.20260518",
    "types-pexpect>=4.9.0.20260518",
    "types-psutil>=7.2.2.20260518",
    "types-pyasn1>=0.6.0.20260408",
    "types-pyaudio>=0.2.16.20260508",
    "types-pygments>=2.20.0.20260518",
    "types-pysocks>=1.7.1.20260518",
    "types-python-dateutil>=2.

{
  "name": "@dietrichgebert/ponytail",
  "version": "4.9.0",
  "description": "Lazy senior dev mode for AI agents. The best code is the code you never wrote.",
  "keywords": ["opencode-plugin", "opencode", "ponytail", "pi-package", "pi", "skills", "qoder"],
  "license": "MIT",
  "author": {
    "name": "Dietrich Gebert",
    "url": "https://github.com/DietrichGebert"
  },
  "homepage": "https://github.com/DietrichGebert/ponytail",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DietrichGebert/ponytail.git"
  },
  "bugs": {
    "url": "https://github.com/DietrichGebert/ponytail/issues"
  },
  "main": "./.opencode/plugins/ponytail.mjs",
  "exports": {
    ".": "./.opencode/plugins/ponytail.mjs",
    "./plugin": "./.opencode/plugins/ponytail.mjs"
  },
  "files": [
    "AGENTS.md",
    "hooks/",
    "skills/",
    ".opencode/",
    ".qoder/",
    ".qoder-plugin/",
    "pi-extension/",
    "scripts/uninstall.js",
    "assets/",
    "LICENSE"
  ],
  "scripts": {
    "test": "node --test tests/*.test.js && npm test --prefix pi-extension && npm test --prefix ponytail-mcp"
  },
  "pi": {
    "extensions": ["./pi-extension/index.js"],
    "skills": ["./skills"]
  },
  "publishConfig": {
    "access": "public"
  }
}
